ValidationRule.errorConditionFormula:
AND(
    OR(RecordType.DeveloperName = "NewOperationalTest", RecordType.DeveloperName = "OldNewOperationalTest"),
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ1 顧客訪問・商品紹介"),
            OR(
                NOT(INCLUDES(CompletionBasis__c, "1-1:お客様を訪問、または非対面で面談し、当社の紹介を行った。")),
                NOT(INCLUDES(CompletionBasis__c, "1-2:お客様との商談から、仮説に対して意見をいただいた。")),
                NOT(INCLUDES(CompletionBasis__c, "1-3:次回商談の日程を確定した。"))
            )
         )
    )
)
